let sharedBackend=null,sessionInfo=null,authReady=!sharedConfigured,appError='',storageIssue='',rawBackup='',state,divisionData,unsubscribeShared=()=>{},unsubscribeAuth=()=>{},remoteRefreshTimer=0,pendingRemote=false,invitations=[],accessRoster={profiles:[],memberships:[],approvers:[]},notifications=[],projectCatalog=[],accessProjectId='',projectAccess=[];
