  try{const raw=localStorage.getItem(DIVISION_STORE_KEY);divisionData=raw?JSON.parse(raw):makeDivisionDemoData(today());if(!validateDivisionState(divisionData).ok)throw new Error('Invalid division preview');if(!raw)localStorage.setItem(DIVISION_STORE_KEY,JSON.stringify(divisionData));}catch{divisionData=makeDivisionDemoData(today());}
