const statusIcon=s=>`<svg class="status-icon" viewBox="0 0 16 16" aria-hidden="true">${({todo:'<circle cx="8" cy="8" r="5.7"/>',progress:'<circle cx="8" cy="8" r="5.7" opacity=".35"/><path d="M8 2.3a5.7 5.7 0 0 1 5.7 5.7" stroke-width="2.4"/>',blocked:'<path d="M7 2.8a1.2 1.2 0 0 1 2 0l5.1 9a1.2 1.2 0 0 1-1 1.8H2.9a1.2 1.2 0 0 1-1-1.8z"/><path d="M8 6v3 M8 11v.1"/>',done:'<circle cx="8" cy="8" r="7" fill="currentColor" stroke="none"/><path d="m4.8 8 2.1 2.1 4.2-4.2" stroke="white"/>',late:'<circle cx="8" cy="8" r="5.7"/><path d="M8 4.5V8l2 1.3"/>'})[s]||''}</svg>`;
