function field(label,name,type,value,extra='',full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" class="input" name="${name}" type="${type}" value="${h(value)}" ${extra}></div>`;}
function selectField(label,name,html,full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><select name="${name}" id="f-${name}">${html}</select></div>`;}
function textField(label,name,value){return `<div class="field full"><label for="f-${name}">${label}</label><textarea name="${name}" id="f-${name}" maxlength="4000">${h(value)}</textarea></div>`;}
function openDialog(title,content,actions='',context=null){previousFocus=document.activeElement;dialogContext=context;$('#editor').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${h(title)}</h2>${button(icon('close'),'close-dialog','aria-label="Close dialog"','icon-only')}</div>${content}${actions}`;$('#editor').showModal();$('#editor').querySelector('input:not([type=hidden])')?.focus();}
function closeDialog(){const id=dialogContext?.id;$('#editor').close();dialogContext=null;if(previousFocus?.isConnected)previousFocus.focus();else if(id)document.querySelector(`[data-id="${CSS.escape(id)}"]`)?.focus();if(pendingRemote)refreshShared(true);}
function formDialog(title,fields,context,deleteAction=''){
  openDialog(title,`<form id="edit-form"><div class="dialog-body"><div id="form-error" role="alert" tabindex="-1" hidden></div><div class="form-grid">${fields}</div></div><div class="dialog-actions">${deleteAction?button(icon('trash')+'Delete',deleteAction,`data-id="${h(context.id)}" type="button"`,'danger'):''}${button('Cancel','close-dialog','type="button"')}<button class="button primary" type="submit">Save ${context.kind}</button></div></form>`,'',context);
}
function taskDialog(id='',projectId=''){
  if(!state.projects.length){projectDialog();toast('Create a project first, then add its tasks.');return;}
  const t=state.tasks.find(t=>t.id===id)||{id:uid(),title:'',projectId:projectId||((ui.project!=='all'&&project(ui.project))?ui.project:state.projects[0].id),assignee:state.profile.memberId,start:today(),end:addDays(today(),3),status:'todo',priority:'medium',description:'',dependsOn:''};
  const deps=()=>options([['','No dependency'],...state.tasks.filter(x=>x.projectId===t.projectId&&x.id!==t.id).map(x=>[x.id,x.title])],t.dependsOn);
  formDialog(id?'Edit task':'New task',field('Task title','title','text',t.title,'required maxlength="120"',true)+selectField('Project','projectId',projectOptions(t.projectId))+selectField('Assignee','assignee',memberOptions(t.assignee))+field('Start date','start','date',t.start,'required')+field('Due date','end','date',t.end,'required')+selectField('Status','status',options(Object.entries(STATUSES),t.status))+selectField('Priority','priority',options([['low','Low'],['medium','Medium'],['high','High']],t.priority))+selectField('Depends on','dependsOn',deps(),true)+textField('Notes / blocker','description',t.description),{kind:'task',id:t.id,existing:!!id},id?'delete-task':'');
  $('#f-projectId').addEventListener('change',e=>{$('#f-dependsOn').innerHTML=options([['','No dependency'],...state.tasks.filter(x=>x.projectId===e.target.value&&x.id!==t.id).map(x=>[x.id,x.title])],'');});
}
function projectDialog(id=''){const p=project(id)||{id:uid(),name:'',description:'',owner:state.profile.memberId,division:'Marketing, Communication & IT',start:today(),end:addDays(today(),14),color:state.projects.length%4};formDialog(id?'Edit project':'New project',field('Project name','name','text',p.name,'required maxlength="100"',true)+selectField('Division','division',options(DIVISIONS,p.division))+selectField('Project lead','owner',memberOptions(p.owner))+field('Start date','start','date',p.start,'required')+field('Target date','end','date',p.end,'required')+selectField('Artwork palette','color',options([['0','Peach & blue'],['1','Butter & sage'],['2','Sage & sky'],['3','Peach, butter & sage']],String(p.color)),true)+textField('Project description','description',p.description),{kind:'project',id:p.id,existing:!!id},id?'delete-project':'');}
function eventDialog(id='',date=''){const e=state.events.find(e=>e.id===id)||{id:uid(),title:'',projectId:ui.project==='all'?'':ui.project,date:date||(route().page==='calendar'?ui.selectedDay:today()),time:'09:00',duration:60,location:'',notes:''};formDialog(id?'Edit event':'New event',field('Event title','title','text',e.title,'required maxlength="120"',true)+selectField('Project','projectId',options([['','Personal / organization'],...state.projects.map(p=>[p.id,p.name])],e.projectId),true)+field('Date','date','date',e.date,'required')+field('Start time','time','time',e.time,'required')+field('Duration (minutes)','duration','number',e.duration,'required min="15" max="480" step="15"')+field('Location / meeting link','location','text',e.location,'maxlength="500"')+textField('Agenda / notes','notes',e.notes),{kind:'event',id:e.id,existing:!!id},id?'delete-event':'');}
function memberDialog(id=''){const m=member(id)||{id:uid(),name:''};formDialog(id?'Edit member':'Add a member',field('Display name','name','text',m.name,'required maxlength="60"',true),{kind:'member',id:m.id,existing:!!id});}
function clearFieldErrors(){document.querySelectorAll('.field-error').forEach(el=>el.remove());document.querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');});}
function formError(message){clearFieldErrors();const el=$('#form-error');el.hidden=false;el.className='form-error';el.textContent=message;const field=/dependency|dependent/i.test(message)?'dependsOn':/due date|end date|Project dates/i.test(message)?'end':/date and time/i.test(message)?'date':/duration/i.test(message)?'duration':/assignee/i.test(message)?'assignee':/lead/i.test(message)?'owner':/division/i.test(message)?'division':/title/i.test(message)?'title':/name/i.test(message)?'name':/project/i.test(message)?'projectId':'';const input=field&&document.querySelector(`#f-${field}`);if(input){const error=document.createElement('p');error.className='field-error';error.id=`error-${field}`;error.textContent=message;input.parentElement.append(error);input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',error.id);input.focus();}else el.focus();}
document.addEventListener('submit',async e=>{if(e.target.id!=='edit-form')return;e.preventDefault();clearFieldErrors();$('#form-error').hidden=true;const c=dialogContext;const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=data[k].trim());data.id=c.id;let next=structuredClone(state),error='';
  if(c.kind==='task'){error=taskError(data,state);if(!error)next=applyTask(state,data);}
  if(c.kind==='project'){data.color=Number(data.color);error=projectError(data,state);if(!error){const ts=state.tasks.filter(t=>t.projectId===data.id);if(ts.length&&(ts.some(t=>t.start<data.start)||ts.some(t=>t.end>data.end)))error='Project dates must include existing tasks. Adjust task dates first or expand the project range.';}if(!error){const old=next.projects.findIndex(p=>p.id===data.id);if(old<0)next.projects.push(data);else next.projects[old]=data;}}
  if(c.kind==='event'){data.duration=Number(data.duration);error=eventError(data,state);if(!error){const old=next.events.findIndex(x=>x.id===data.id);if(old<0)next.events.push(data);else next.events[old]=data;}}
  if(c.kind==='member'){if(!data.name)error='Enter a display name.';data.initials=initials(data.name);if(!error){const old=next.members.findIndex(x=>x.id===data.id);if(old<0)next.members.push(data);else next.members[old]=data;if(data.id===next.profile.memberId)next.profile.name=data.name;}}
  if(error){formError(error);return;}const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Saving…';try{if(await save(next,`${c.existing?'Updated':'Created'} ${c.kind}: ${data.title||data.name}`)){closeDialog();}else formError(appError||'The change could not be saved. Your draft is still here.');}finally{if(submit.isConnected){submit.disabled=false;submit.textContent=`Save ${c.kind}`;}}
});
function confirmDelete(kind,id){const item=(kind==='project'?state.projects:kind==='task'?state.tasks:state.events).find(x=>x.id===id);if(!item)return;$('#editor').close();const detail=kind==='project'?`This removes the project, its ${state.tasks.filter(t=>t.projectId===id).length} tasks, linked events, milestones, blockers, and documents.${sharedConfigured?' This shared deletion cannot be undone.':' You can undo this change.'}`:kind==='task'?'This also clears links from tasks that depend on it. You can undo this change.':'You can undo this change.';openDialog(`Delete ${kind}?`,`<div class="dialog-body"><p><strong>${h(item.name||item.title)}</strong></p><p class="muted small" style="margin-top:12px">${detail}</p></div>`,`<div class="dialog-actions">${button('Cancel','close-dialog')}${button('Delete '+kind,'confirm-delete',`data-kind="${kind}" data-id="${h(id)}"`,'danger')}</div>`,{kind:'confirm',id});}
async function changeStatus(id,status){const t=state.tasks.find(t=>t.id===id);if(!t)return;try{const result=await save(applyTask(state,{...t,status}),`${status==='done'?'Completed':'Updated'} task: ${t.title}`);if(!result)render();}catch(e){render();toast(e.message);}}
function monthShift(date,n){const d=day(date);return iso(new Date(d.getFullYear(),d.getMonth()+n,1));}
function exportBackup(){const text=sharedConfigured?localStorage.getItem(STORE_KEY):storageIssue&&rawBackup?rawBackup:JSON.stringify(state,null,2);if(!text){toast('No local v1 backup exists in this browser.');return;}const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=`dwdg-workspace-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Local backup exported.');}
function legacyMapFromDialog(){return Object.fromEntries([...document.querySelectorAll('[data-legacy-member]')].filter(x=>x.value).map(x=>[x.dataset.legacyMember,x.value]));}
function showLegacyPreview(data,memberMap={},serverPreview=null,importId=crypto.randomUUID()){
  const preview=previewLegacyBackup(data,memberMap);
  const rows=data.members.map(m=>`<div class="v03-legacy-map-row"><span>${h(m.name)}</span><select data-legacy-member="${h(m.id)}" aria-label="Map ${h(m.name)} to invited member">${options([['','Choose account'],...state.members.map(x=>[x.id,x.name])],memberMap[m.id])}</select></div>`).join('');
  const issues=[...preview.unknownDivisions.map(x=>`Unknown division: ${h(x)}`),...preview.invalidLinks.map(x=>`Broken record link: ${h(x)}`)].map(x=>`<li>${x}</li>`).join('');
  const result=serverPreview?`<div class="notice" role="status"><strong>Server preview complete.</strong> ${h(JSON.stringify(serverPreview))}</div>`:'';
  if($('#editor').open)$('#editor').close();
  openDialog('Review old workspace backup',`<div class="dialog-body"><p>${preview.counts.projects} projects, ${preview.counts.tasks} tasks, and ${preview.counts.meetings} meetings. No records are uploaded until you commit.</p>${preview.renamedDivisions.length?'<p class="small muted">Client Engagement will be mapped to External Engagement.</p>':''}<h3>Match legacy names to invited accounts</h3><div class="v03-legacy-map">${rows}</div>${issues?`<ul class="notice error">${issues}</ul>`:''}${result}<p class="small muted">Review all mappings before importing. Existing browser data remains untouched.</p></div>`,`<div class="dialog-actions">${button('Cancel','close-dialog')}${button('Preview on server','preview-import','','primary')}${serverPreview&&preview.ready?button('Commit import','confirm-import','','primary'):''}</div>`,{kind:'legacy-import',data,memberMap,importId,serverPreview});
}
async function commitLegacyImport(){const c=dialogContext;if(!c||c.kind!=='legacy-import'||!c.serverPreview)return;const map=legacyMapFromDialog();const current=previewLegacyBackup(c.data,map);if(!current.ready){toast('Map every member before importing.');return;}if(JSON.stringify(map)!==JSON.stringify(c.memberMap)){showLegacyPreview(c.data,map,null,c.importId);toast('Mappings changed. Preview them again before committing.');return;}const buttonEl=$('[data-action="confirm-import"]');buttonEl.disabled=true;try{await sharedBackend.importLegacyBackup(c.data,map,false,c.importId);closeDialog();await refreshShared(true);toast('Legacy workspace imported.');}catch(error){buttonEl.disabled=false;toast(error.message);}}
function openMenu(){openDialog('Navigation',`<div class="dialog-body menu-panel">${[['home','Home','home'],['tasks','My Work','tasks'],['calendar','Schedule','calendar'],['updates','Updates','flag'],['projects','All Projects','projects'],['gantt','Timeline','gantt'],['settings','Settings','settings']].map(([id,label,i])=>`<a href="#${id}" data-menu-link>${icon(i)}${label}</a>`).join('')}<p class="nav-label">WORKSPACES</p>${divisionRoutes.map(([slug,label,i])=>`<a href="#workspace/${slug}" data-menu-link>${icon(i)}${h(label)}</a>`).join('')}</div>`);}
function openWorkspacesMenu(){openDialog('Choose workspace',`<div class="dialog-body menu-panel"><a href="#home" data-menu-link>${icon('home')}Personal Home</a>${divisionRoutes.map(([slug,label,i])=>`<a href="#workspace/${slug}" data-menu-link>${icon(i)}<span>${h(label)}${['external-engagement','consulting'].includes(slug)?'<small class="sub">Shared summary</small>':''}</span></a>`).join('')}</div>`);}
function searchResults(query){const q=query.trim().toLowerCase();if(!q)return '<p class="v03-empty">Search projects, tasks, and divisions.</p>';const found=[...state.projects.filter(p=>`${p.name} ${p.division}`.toLowerCase().includes(q)).map(p=>({label:p.name,meta:`Project · ${p.division}`,href:`#projects/${p.id}`})),...catalogOnly().filter(item=>`${item.name} ${catalogDivision(item)}`.toLowerCase().includes(q)).map(item=>({label:item.name,meta:`Shared summary · ${catalogDivision(item)}`,href:'#projects'})),...state.tasks.filter(t=>`${t.title} ${project(t.projectId)?.name||''}`.toLowerCase().includes(q)).map(t=>({label:t.title,meta:`Task · ${project(t.projectId)?.name||'Project'}`,href:'#tasks'})),...divisionRoutes.filter(([,label])=>label.toLowerCase().includes(q)).map(([slug,label])=>({label,meta:'Division workspace',href:`#workspace/${slug}`}))].slice(0,12);return found.length?found.map(x=>`<a class="v03-search-result" href="${h(x.href)}" data-menu-link><strong>${h(x.label)}</strong><span>${h(x.meta)}</span></a>`).join(''):'<p class="v03-empty">No permitted results match your search.</p>';}
function openGlobalSearch(){openDialog('Search workspace',`<div class="dialog-body"><label class="sr-only" for="global-search-input">Search projects, tasks, and divisions</label><input class="input" id="global-search-input" type="search" autocomplete="off" placeholder="Find a project, task, or division…"><div id="global-search-results" class="v03-search-results">${searchResults('')}</div></div>`);$('#global-search-input').focus();}
document.addEventListener('click',async e=>{if(e.target.closest('[data-menu-link]'))closeDialog();const b=e.target.closest('[data-action]');if(!b){const row=e.target.closest('[data-task-row]');if(row&&!e.target.closest('input,select,label,button,a')&&!window.getSelection()?.toString())taskDialog(row.dataset.taskRow);return;}const a=b.dataset.action,id=b.dataset.id;if(discardClick&&a==='edit-task'){discardClick=false;return;}
  switch(a){
    case 'new-task':taskDialog('',b.dataset.project);break;case 'edit-task':taskDialog(id);break;
    case 'new-project':projectDialog();break;case 'edit-project':projectDialog(id);break;
    case 'open-project':go('projects/'+id);break;case 'navigate':go(b.dataset.to);break;
    case 'new-event':eventDialog('',b.dataset.date);break;case 'edit-event':eventDialog(id);break;
    case 'new-member':memberDialog();break;case 'edit-member':memberDialog(id);break;
    case 'close-dialog':closeDialog();break;case 'undo':undo();break;
    case 'delete-task':confirmDelete('task',id);break;case 'delete-project':confirmDelete('project',id);break;case 'delete-event':confirmDelete('event',id);break;
    case 'confirm-delete':{const k=b.dataset.kind;let next=structuredClone(state);if(k==='task')next=deleteTask(state,id);if(k==='event')next.events=next.events.filter(x=>x.id!==id);if(k==='project'){next.projects=next.projects.filter(x=>x.id!==id);next.tasks=next.tasks.filter(x=>x.projectId!==id);next.events=next.events.filter(x=>x.projectId!==id);}b.disabled=true;if(await save(next,`Deleted ${k}.`)){closeDialog();if(k==='project')go('projects');}else b.disabled=false;break;}
    case 'mine':ui.assignee=ui.assignee===state.profile.memberId?'all':state.profile.memberId;render();break;
    case 'layout':ui.layout=b.dataset.layout;render();break;
    case 'project-timeline':go('gantt');ui.project=b.dataset.project;ui.gantt=project(b.dataset.project)?.start||today();render();break;
    case 'calendar-prev':ui.calendar=monthShift(ui.calendar,-1);ui.selectedDay=ui.calendar;render();break;case 'calendar-next':ui.calendar=monthShift(ui.calendar,1);ui.selectedDay=ui.calendar;render();break;case 'calendar-today':ui.calendar=today();ui.selectedDay=today();render();break;case 'select-day':ui.selectedDay=b.dataset.date;render();break;
    case 'calendar-mode':ui.calendarMode=b.dataset.mode;render();break;
    case 'day-agenda':openDialog(fullDate(b.dataset.date),`<div>${agendaRange(b.dataset.date,b.dataset.date)}</div>`);break;
    case 'zoom':ui.zoom=b.dataset.zoom;render();break;
    case 'gantt-prev':ui.gantt=ui.zoom==='month'?monthShift(ui.gantt,-1):addDays(ui.gantt,-14);render();break;
    case 'gantt-next':ui.gantt=ui.zoom==='month'?monthShift(ui.gantt,1):addDays(ui.gantt,14);render();break;
    case 'gantt-today':ui.gantt=today();render();break;
    case 'chart-range':ui.chartDays=Number(b.dataset.days)===30?30:7;render();document.querySelector(`[data-days="${ui.chartDays}"]`)?.focus();break;
    case 'chart-detail':{const date=b.dataset.date;const ts=state.tasks.filter(t=>t.status==='done'&&t.completedAt===date);$('#chart-note').textContent=`${fmt(date)} · ${ts.length} completed${ts.length?': '+ts.map(t=>t.title).join(', '):'.'}`;break;}
    case 'mobile-menu':openMenu();break;case 'workspaces-menu':openWorkspacesMenu();break;case 'global-search':openGlobalSearch();break;case 'settings':go('settings');break;case 'export':exportBackup();break;case 'import':$('#import-file').click();break;
    case 'sign-in':try{appError='';await sharedBackend.signInWithGoogle(location.href);}catch(error){appError=error.message;render();}break;
    case 'retry-session':try{appError='';if(!sharedBackend){await initializeShared();break;}sessionInfo=await sharedBackend.bootstrap();if(sessionInfo){await refreshShared(true);watchShared();}render();}catch(error){appError=error.message;render();}break;
    case 'switch-account':try{await sharedBackend.signOut();sessionInfo=null;await sharedBackend.signInWithGoogle(location.href);}catch(error){appError=error.message;render();}break;
    case 'sign-out':try{await sharedBackend.signOut();unsubscribeShared();sessionInfo=null;render();}catch(error){toast(error.message);}break;
    case 'revoke-invite':if(!sessionInfo?.canManageInvitations)break;try{b.disabled=true;await sharedBackend.revokeInvitation(b.dataset.email);invitations=await sharedBackend.listInvitations();render();toast('Invitation revoked.');}catch(error){b.disabled=false;toast(error.message);}break;
    case 'mark-notification':if(!sharedBackend)break;try{b.disabled=true;await sharedBackend.markNotificationRead(id);notifications=await sharedBackend.listNotifications();render();}catch(error){b.disabled=false;toast(error.message);}break;
    case 'load-project-access':if(!sessionInfo?.canManageInvitations)break;try{const selected=$('#project-access-form [name="projectId"]')?.value;if(!selected)throw new Error('Choose a project first.');b.disabled=true;projectAccess=await sharedBackend.listProjectAccess(selected);accessProjectId=selected;render();}catch(error){b.disabled=false;toast(error.message);}break;
    case 'remove-project-access':if(!sessionInfo?.canManageInvitations)break;try{b.disabled=true;await sharedBackend.removeProjectAccess(b.dataset.project,b.dataset.user);projectAccess=await sharedBackend.listProjectAccess(b.dataset.project);render();toast('Project access removed.');}catch(error){b.disabled=false;toast(error.message);}break;
    case 'preview-import':{const c=dialogContext;if(!c||c.kind!=='legacy-import')break;const map=legacyMapFromDialog();const preview=previewLegacyBackup(c.data,map);if(!preview.ready){toast('Map every member and resolve backup errors first.');showLegacyPreview(c.data,map,null,c.importId);break;}b.disabled=true;try{const result=await sharedBackend.importLegacyBackup(c.data,map,true,c.importId);showLegacyPreview(c.data,map,result,c.importId);}catch(error){b.disabled=false;toast(error.message);}break;}
    case 'confirm-import':{if(sharedConfigured){await commitLegacyImport();break;}const next=dialogContext.data;if(await save(next,'Imported workspace backup.')){closeDialog();go('home');}break;}
    case 'recover':openDialog('Replace unreadable saved data?',`<div class="dialog-body"><p>Export the original backup first if you want to keep it. This saves the current session as your browser workspace.</p></div>`,`<div class="dialog-actions">${button('Cancel','close-dialog')}${button('Save current session','confirm-recover','','primary')}</div>`);break;
    case 'confirm-recover':try{localStorage.setItem(STORE_KEY,JSON.stringify(state));storageIssue='';rawBackup='';closeDialog();render();toast('Current workspace saved.');}catch{toast('Browser storage is unavailable. Export a backup to keep this session.');}break;
  }
});
document.addEventListener('input',e=>{if(e.target.closest('.field')&&e.target.hasAttribute('aria-invalid')){e.target.removeAttribute('aria-invalid');e.target.removeAttribute('aria-describedby');e.target.closest('.field').querySelector('.field-error')?.remove();}if(e.target.matches('[data-search]')){ui.search=e.target.value;render();}if(e.target.id==='global-search-input')$('#global-search-results').innerHTML=searchResults(e.target.value);});
document.addEventListener('change',e=>{if(e.target.dataset.statusTask){const id=e.target.dataset.statusTask;changeStatus(id,e.target.value);const controls=[...document.querySelectorAll('[data-status-task]')];controls.find(x=>x.dataset.statusTask===id&&x.getClientRects().length)?.focus();return;}const f=e.target.dataset.filter;if(f){ui[f]=e.target.value;render();}if(e.target.dataset.complete)changeStatus(e.target.dataset.complete,e.target.checked?'done':'todo');});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>3*1024*1024)throw new Error('Backup must be smaller than 3 MB.');const data=JSON.parse(await file.text());if(!validateState(data))throw new Error('This file is not a valid DWDG workspace backup.');if(sharedConfigured){if(!sessionInfo?.canManageInvitations)throw new Error('Only a Super Admin can import a legacy backup.');showLegacyPreview(data);return;}openDialog('Import workspace?',`<div class="dialog-body"><p>This replaces your current workspace with ${data.projects.length} projects, ${data.tasks.length} tasks, and ${data.events.length} events.</p><p class="muted small" style="margin-top:12px">Export your current workspace first if you want a separate backup. Import can also be undone immediately.</p></div>`,`<div class="dialog-actions">${button('Cancel','close-dialog')}${button('Import workspace','confirm-import','','primary')}</div>`,{kind:'import',data});}catch(err){toast(err.message);}});
$('#editor').addEventListener('cancel',()=>{dialogContext=null;});
$('#editor').addEventListener('click',e=>{if(e.target===$('#editor')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
let draggedId='';document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-task]');if(card){draggedId=card.dataset.dragTask;e.dataTransfer.setData('text/plain',draggedId);e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop-status]');if(col&&draggedId){e.preventDefault();col.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-drop-status]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over');});
document.addEventListener('drop',e=>{const col=e.target.closest('[data-drop-status]');if(col&&draggedId){e.preventDefault();changeStatus(draggedId,col.dataset.dropStatus);draggedId='';}});
document.addEventListener('dragend',()=>{draggedId='';document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));});
document.addEventListener('keydown',async e=>{const bar=e.target.closest('[data-gantt-task]');if(!bar)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();taskDialog(bar.dataset.ganttTask);}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const id=bar.dataset.ganttTask;try{const next=shiftTask(state,id,e.key==='ArrowRight'?1:-1,e.shiftKey);const saved=await save(next,'Rescheduled task: '+state.tasks.find(t=>t.id===id).title);if(!saved)render();document.querySelector(`[data-gantt-task="${CSS.escape(id)}"]`)?.focus();}catch(err){render();toast(err.message);}}});
document.addEventListener('pointerdown',e=>{const bar=e.target.closest('[data-gantt-task]');if(!bar||e.button!==0)return;const id=bar.dataset.ganttTask;const resize=!!e.target.closest('.resize-handle');const startX=e.clientX;const initialLeft=parseFloat(bar.style.left),initialWidth=parseFloat(bar.style.width);let delta=0,moved=false;bar.setPointerCapture(e.pointerId);
  const move=ev=>{if(Math.abs(ev.clientX-startX)<5&&!moved)return;moved=true;bar.classList.add('dragging');delta=Math.round((ev.clientX-startX)/ganttRange().width);if(resize)bar.style.width=Math.max(12,initialWidth+delta*ganttRange().width)+'px';else bar.style.left=initialLeft+delta*ganttRange().width+'px';};
  const finish=async()=>{bar.removeEventListener('pointermove',move);bar.removeEventListener('pointerup',finish);bar.removeEventListener('pointercancel',cancel);bar.classList.remove('dragging');if(!moved)return;discardClick=true;setTimeout(()=>discardClick=false,100);if(delta){try{const next=shiftTask(state,id,delta,resize);if(!await save(next,'Rescheduled task: '+state.tasks.find(t=>t.id===id).title))render();}catch(err){render();toast(err.message);}}else render();};
  const cancel=()=>{bar.removeEventListener('pointermove',move);bar.removeEventListener('pointerup',finish);bar.removeEventListener('pointercancel',cancel);render();};bar.addEventListener('pointermove',move);bar.addEventListener('pointerup',finish);bar.addEventListener('pointercancel',cancel);
});
window.addEventListener('hashchange',()=>{ui.search='';ui.status='all';ui.assignee=route().page==='tasks'?state.profile.memberId:'all';if(route().page!=='gantt')ui.project='all';ui.division='all';render();window.scrollTo({top:0,left:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(sharedConfigured||e.key!==STORE_KEY||!e.newValue)return;try{const updated=JSON.parse(e.newValue);if(validateState(updated)){state=updated;undoState=null;render();toast('Workspace updated in another tab.');}}catch{}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#editor').open)openGlobalSearch();}});
if(route().page==='tasks')ui.assignee=state.profile.memberId;
mountPrism(document);
render();
if(sharedConfigured)initializeShared();

document.addEventListener('submit',async event=>{
  const form=event.target;if(!['invite-form','membership-form','remove-membership-form','role-form','approver-form','project-access-form'].includes(form.id))return;
  event.preventDefault();if(!sessionInfo?.canManageInvitations)return;
  const data=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type="submit"]');const errorEl=form.querySelector('.v03-form-error');errorEl.hidden=true;submit.disabled=true;
  try{
    if(form.id==='invite-form'){await sharedBackend.createInvitation(data);invitations=await sharedBackend.listInvitations();toast('Invitation created. The member can now sign in with Google.');}
    else if(form.id==='membership-form'){await sharedBackend.setMembership(data.userId,data.divisionCode,data.role);toast('Division membership updated.');}
    else if(form.id==='remove-membership-form'){await sharedBackend.removeMembership(data.userId,data.divisionCode);toast('Division membership removed.');}
    else if(form.id==='role-form'){await sharedBackend.setGlobalRole(data.userId,data.role,data.active==='true');toast('Account access updated.');}
    else if(form.id==='approver-form'){await sharedBackend.setFinanceApprover(data.userId,data.enabled==='true');toast('Finance approval access updated.');}
    else if(form.id==='project-access-form'){await sharedBackend.setProjectAccess(data.projectId,data.userId,data.role);accessProjectId=data.projectId;projectAccess=await sharedBackend.listProjectAccess(data.projectId);toast('Project access updated.');}
    if(form.id!=='invite-form')accessRoster=await sharedBackend.listMembersWithAccess();
    render();
  }catch(error){errorEl.textContent=error.message;errorEl.hidden=false;submit.disabled=false;}
});

function adminSettingsPage(){
  if(!sharedConfigured||!sessionInfo?.canManageInvitations)return '';
  const inviteRows=invitations.slice(0,15).map(x=>`<div class="v03-row"><div class="v03-row-main"><strong>${h(x.email)}</strong><span class="sub">${h(x.primary_division_code||'Organization')} · ${h(x.division_role||'member')}</span></div><span class="v03-badge" data-tone="${x.revoked_at?'warning':'success'}">${x.revoked_at?'Revoked':'Invited'}</span>${x.revoked_at?'':button('Revoke','revoke-invite',`data-email="${h(x.email)}"`)}</div>`).join('')||'<div class="v03-empty">No invitations yet.</div>';
  const members=accessRoster.profiles.map(x=>`<div class="v03-row"><div class="v03-row-main"><strong>${h(x.full_name||x.email)}</strong><span class="sub">${h(x.email)} · ${h(x.global_role)} · ${accessRoster.memberships.filter(m=>m.user_id===x.id).map(m=>h(m.division_code)+' ('+h(m.role)+')').join(', ')||'No division membership'}</span></div></div>`).join('')||'<div class="v03-empty">No signed-in members yet.</div>';
  const divisions=divisionRoutes.map(([,label])=>[DIVISION_CODES[label],label]);
  return `<section class="v03-admin-access"><div class="v03-page-head"><div><span class="v03-eyebrow">SUPER ADMIN</span><h2>Access and invitations</h2><p>Only invited Google accounts can join. Membership controls editing; visibility follows database permissions.</p></div></div><div class="v03-grid-2"><section class="v03-panel"><div class="v03-panel-head"><h3>Invite a member</h3></div><form id="invite-form" class="v03-admin-form"><div class="v03-form-error" role="alert" hidden></div><label>Email<input class="input" name="email" type="email" autocomplete="email" required></label><label>Primary division<select name="divisionCode">${options(divisions,'strategy_growth')}</select></label><label>Division role<select name="divisionRole">${options([['viewer','Viewer'],['member','Member'],['division_head','Division head']],'member')}</select></label><button class="button primary" type="submit">Create invitation</button></form><div class="v03-list">${inviteRows}</div></section><section class="v03-panel"><div class="v03-panel-head"><h3>Member access</h3></div><form id="membership-form" class="v03-admin-form"><div class="v03-form-error" role="alert" hidden></div><label>Member<select name="userId">${options(state.members.map(x=>[x.id,x.name]),'')}</select></label><label>Division<select name="divisionCode">${options(divisions,'strategy_growth')}</select></label><label>Role<select name="role">${options([['viewer','Viewer'],['member','Member'],['division_head','Division head']],'member')}</select></label><button class="button primary" type="submit">Update membership</button></form><div class="v03-list">${members}</div></section></div></section>`;
}
function adminManagementPanels(){
  if(!sharedConfigured||!sessionInfo?.canManageInvitations)return '';
  const people=options(accessRoster.profiles.map(p=>[p.id,p.full_name||p.email]),'');
  const divisions=options(divisionRoutes.map(([,label])=>[DIVISION_CODES[label],label]),'');
  const projects=options(state.projects.map(p=>[p.id,p.name]),accessProjectId);
  const grants=projectAccess.map(grant=>`<div class="v03-row"><div class="v03-row-main"><strong>${h(accessRoster.profiles.find(p=>p.id===grant.user_id)?.full_name||grant.user_id)}</strong><span class="sub">${h(grant.role)}</span></div>${button('Remove','remove-project-access',`data-project="${h(grant.project_id)}" data-user="${h(grant.user_id)}"`)}</div>`).join('')||'<div class="v03-empty">No direct access grants loaded for this project.</div>';
  return `<div class="v03-admin-access v03-grid-2">
    <section class="v03-panel"><div class="v03-panel-head"><h3>Member roles</h3></div>
      <form id="role-form" class="v03-admin-form"><div class="v03-form-error" role="alert" hidden></div><label>Member<select name="userId" required>${people}</select></label><label>Organization role<select name="role">${options([['member','Member'],['super_admin','Super Admin']],'member')}</select></label><label>Account<select name="active">${options([['true','Active'],['false','Inactive']],'true')}</select></label><button class="button primary" type="submit">Update account</button></form>
      <form id="approver-form" class="v03-admin-form"><div class="v03-form-error" role="alert" hidden></div><label>Member<select name="userId" required>${people}</select></label><label>Finance approval<select name="enabled">${options([['true','Designated approver'],['false','No approval access']],'true')}</select></label><button class="button primary" type="submit">Update approver</button></form>
      <form id="remove-membership-form" class="v03-admin-form"><div class="v03-form-error" role="alert" hidden></div><label>Member<select name="userId" required>${people}</select></label><label>Division<select name="divisionCode">${divisions}</select></label><button class="button" type="submit">Remove membership</button></form>
    </section>
    <section class="v03-panel"><div class="v03-panel-head"><h3>Project access</h3></div>
      <form id="project-access-form" class="v03-admin-form"><div class="v03-form-error" role="alert" hidden></div><label>Project<select name="projectId" required>${projects}</select></label><label>Member<select name="userId" required>${people}</select></label><label>Access<select name="role">${options([['viewer','Viewer'],['editor','Editor'],['lead','Lead']],'viewer')}</select></label><div class="actions"><button class="button primary" type="submit">Grant access</button>${button('View grants','load-project-access','type="button"')}</div></form>
      <div class="v03-list">${grants}</div>
    </section>
  </div>`;
}
function notificationPanel(){
  if(!sharedConfigured)return '';
  const rows=notifications.slice(0,30).map(n=>`<div class="v03-row ${n.read_at?'':'v03-unread'}"><span class="v03-activity-mark"></span><div class="v03-row-main"><strong>${h(n.title)}</strong><span class="sub">${h(new Date(n.created_at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}))}</span></div>${n.read_at?'':button('Mark read','mark-notification',`data-id="${h(n.id)}"`)}</div>`).join('');
  return `<section class="v03-panel v03-notifications"><div class="v03-panel-head"><h2>Notifications</h2><span class="v03-count">${notifications.filter(n=>!n.read_at).length} unread</span></div><div class="v03-list">${rows||'<div class="v03-empty"><strong>You are all caught up.</strong><span>Approvals, assignments, and relevant updates will appear here.</span></div>'}</div></section>`;
}
